var builder = DistributedApplication.CreateBuilder(args);

var db = builder.AddMongoDB("mongo")
                .AddDatabase("db");

builder.AddDockerfile("api", "node")
       .WithHttpEndpoint(targetPort: 3000, env: "PORT")
       .WithReference(db);

builder.Build().Run();
